                    /// </summary>
                    /// <exception cref="InvalidIDException">
                    /// Thrown when the service is not available.
                    /// </exception>
                    /// <exception cref="InvalidIOException">
                    /// Thrown when internal I/O error happen.
                    /// </exception>
                    /// <exception cref="PermissionDeniedException">
                    /// Thrown when the access is denied.
                    /// </exception>
                    public void Connect()
                    {
                        ConnectSync(_actionServiceAppId, _actionServicePortName);
                    }

                    /// <summary>
                    /// Disconnects from the Action Framework service.
                    /// </summary>
                    /// <exception cref="System.InvalidOperationException">
                    /// Thrown when an internal IO error occurrs.
                    /// </exception>
                    public void Disconnect()
                    {
                        // Serialize with Invoke(): it uses the port until its reply arrives.
