                    /// </summary>
                    /// <param name="action_name">The name of the action</param>
                    /// <returns>1 if enabled, 0 if disabled, -1 if this app does not provide the action, -2 on failure</returns>
                    /// <exception cref="NotConnectedSocketException">
                    /// Thrown when the proxy is not connected.
                    /// </exception>
                    /// <exception cref="InvalidIOException">
                    /// Thrown when internal I/O error happen.
                    /// </exception>
                    public int IsProviderEnabled(string action_name)
                    {
